// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 ts1, uint64 ts2, uint256 basefee) public {
        vm.assume(ts1 != ts2);
        vm.startPrank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(1, ts1, basefee, bytes32(uint256(1)), 1, bytes32(uint256(1)), 1, 1);
        c.setL1BlockValues(2, ts2, basefee, bytes32(uint256(2)), 2, bytes32(uint256(2)), 2, 2);
        vm.stopPrank();
        assertTrue(c.timestamp() == ts2);
    }
}
